import{_ as l,o,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2017-JUN-15 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-JUN-15 :: Ceph Performance Weekly","date":"2017-06-21T00:00:00.000Z","updated":"2017-06-22T00:00:00.000Z","tags":["Ceph","Performance Optimization","Distributed Storage","RocksDB","BDPR"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-JUN-15_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-JUN-15_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2017-JUN-15_-_-_Ceph_Performance_Weekly.md"};function s(p,e,n,a,_,g){return o(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年6月15日</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及讨论</p><p><strong>参会人员</strong>： 研发人员、项目经理、测试人员</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph项目进展</strong></p><ol><li><p><strong>新功能与优化</strong>：</p><ul><li>成功合并了降低AC传输成本的代码，并正在进行测试。</li><li>优化了BBQ流程。</li><li>正在测试中，合并了处理高优先级任务的代码，但仍在等待关于“点亮”提交的共识。</li><li>开放了一个新的PR，修改了文件存储中回调函数的顺序，但之前决定不修改。</li><li>讨论了调整缓存大小的代码，允许通过整体蓝鲸或铸币大小来配置Rocks缓存大小。</li><li>讨论了提升缓存大小的内存使用，计划将其提升至3-4GB。</li></ul></li><li><p><strong>性能优化</strong>：</p><ul><li>正在测试中，发现了一个与Rocks存储层相关的bug，需要进一步分析。</li><li>讨论了在Rocks缓存中存储已编码数据的性能影响，以及是否需要进一步的压缩。</li><li>讨论了是否可以通过优化编码速度来提高性能。</li></ul></li><li><p><strong>其他</strong>：</p><ul><li>介绍了OmniDB项目，正在尝试恢复LDPR（Log-Driven Replication）功能。</li><li>讨论了是否需要缩短本周的会议时间。</li></ul></li></ol><p><strong>二、行动计划</strong></p><ol><li>继续测试和优化新功能与性能优化。</li><li>分析Rocks存储层相关的bug，并修复。</li><li>进一步研究Rocks缓存中存储已编码数据的性能影响。</li><li>优化编码速度，提高性能。</li><li>恢复LDPR功能，并评估其性能。</li></ol><p><strong>三、后续会议</strong></p><p>下次会议将根据测试结果和bug修复情况确定。</p><p><strong>四、其他事项</strong></p><p>无。</p><p><strong>改进说明</strong>：</p><ol><li>确保了总结中包含了所有关键细节，包括新功能的合并、性能优化、发现的bug和后续的行动计划。</li><li>保留了所有计算机科学/ceph相关领域的英文原文关键词，如Ceph、RocksDB、BDPR等。</li><li>对部分表述进行了调整，使其更符合中文表达习惯，同时保持了对原始内容的准确反映。</li></ol>',15)])])}const u=l(r,[["render",s]]);export{d as __pageData,u as default};
